package com.waldron.adventurerspack;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.*;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.nbt.CompoundTag;
@GameTestHolder(AdventurersPack.ID)
@PrefixGameTestTemplate(false)
public final class EndgameTests {
 @GameTest(template="empty") public static void transformKeepsIdentity(GameTestHelper h){ItemStack lance=new ItemStack(AdventurersPack.ENDGAME.get());lance.setDamageValue(517);lance.setHoverName(net.minecraft.network.chat.Component.literal("My Endgame"));lance.enchant(Enchantments.UNBREAKING,3);lance.getOrCreateTag().putUUID("AdventurersPackLease",java.util.UUID.randomUUID());ItemStack pick=Endgame.transformed(lance);h.assertTrue(pick.is(AdventurersPack.ENDGAME_PICKAXE.get())&&pick.getDamageValue()==517,"Pick form preserves wear");h.assertTrue(pick.getTag().equals(lance.getTag()),"All enchantments, custom name and lease metadata preserved");ItemStack axe=Endgame.transformed(pick);h.assertTrue(axe.is(AdventurersPack.ENDGAME_AXE.get()),"Axe form reached");ItemStack shovel=Endgame.transformed(axe);h.assertTrue(shovel.is(AdventurersPack.ENDGAME_SHOVEL.get()),"Shovel form reached");ItemStack hoe=Endgame.transformed(shovel);h.assertTrue(hoe.is(AdventurersPack.ENDGAME_HOE.get()),"Hoe form reached");ItemStack back=Endgame.transformed(hoe);h.assertTrue(ItemStack.matches(lance,back),"Full transformation round trip is lossless");h.succeed();}
 @GameTest(template="empty") public static void strongerThanNetherite(GameTestHelper h){ItemStack lance=new ItemStack(AdventurersPack.ENDGAME.get()),pick=new ItemStack(AdventurersPack.ENDGAME_PICKAXE.get());double damage=lance.getAttributeModifiers(EquipmentSlot.MAINHAND).get(Attributes.ATTACK_DAMAGE).stream().mapToDouble(m->m.getAmount()).sum()+1;h.assertTrue(damage==48&&!lance.isDamageableItem()&&!lance.isBarVisible()&&lance.getMaxDamage()==4096&&pick.getMaxDamage()==4096,"Tripled lance damage stays unbreakable across forms");var stone=net.minecraft.world.level.block.Blocks.STONE.defaultBlockState();h.assertTrue(pick.getDestroySpeed(stone)==24f,"Pickaxe mining speed is doubled");h.assertTrue(pick.isCorrectToolForDrops(net.minecraft.world.level.block.Blocks.ANCIENT_DEBRIS.defaultBlockState()),"Endgame mines top-tier ores");h.assertTrue(lance.canPerformAction(net.minecraftforge.common.ToolActions.SWORD_SWEEP),"Lance supports actual sword sweeping");h.succeed();}
 @GameTest(template="empty") public static void returnExactlyOnce(GameTestHelper h){var p=h.makeMockPlayer();ItemStack weapon=new ItemStack(AdventurersPack.ENDGAME.get());weapon.setDamageValue(51);var projectile=new EndgameProjectile(h.getLevel(),p,weapon);projectile.returnSlot=0;h.assertTrue(projectile.returnWeapon(p),"Weapon returns to original slot");h.assertTrue(p.getMainHandItem().is(AdventurersPack.ENDGAME.get())&&p.getMainHandItem().getDamageValue()==51,"Actual durability returned");projectile.returnWeapon(p);int count=0;for(var stack:p.getInventory().items)if(stack.is(AdventurersPack.ENDGAME.get()))count+=stack.getCount();h.assertTrue(count==1,"Repeated return cannot duplicate");h.succeed();}
 @GameTest(template="empty") public static void fullInventoryWaits(GameTestHelper h){var p=h.makeMockPlayer();for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));var e=new EndgameProjectile(h.getLevel(),p,new ItemStack(AdventurersPack.ENDGAME.get()));e.returnSlot=0;h.assertFalse(e.returnWeapon(p),"No return when inventory full");h.assertFalse(e.delivered,"Projectile still owns the weapon");p.getInventory().setItem(12,ItemStack.EMPTY);h.assertTrue(e.returnWeapon(p)&&p.getInventory().getItem(12).is(AdventurersPack.ENDGAME.get()),"Freed space receives weapon without overwriting held stack");h.succeed();}
 @GameTest(template="empty") public static void returnToEquippedToolKit(GameTestHelper h){var p=h.makeMockPlayer();var pack=new ItemStack(AdventurersPack.PACK.get());var id=java.util.UUID.randomUUID();pack.getOrCreateTag().putUUID("AdventurersPackId",id);PackEquipment.get(p).items.setStackInSlot(0,pack);p.getInventory().setItem(0,new ItemStack(Items.TORCH,22));var e=new EndgameProjectile(h.getLevel(),p,new ItemStack(AdventurersPack.ENDGAME.get()));e.homePack=id;e.homeSlot=111;e.returnSlot=0;h.assertTrue(e.returnWeapon(p),"Throw returns to equipped rack");h.assertTrue(new PackData(pack).items.getStackInSlot(111).is(AdventurersPack.ENDGAME.get())&&p.getMainHandItem().getCount()==22,"Home rack receives lance, original hand unchanged");h.succeed();}
 @GameTest(template="empty") public static void projectilePersistence(GameTestHelper h){var p=h.makeMockPlayer();ItemStack weapon=new ItemStack(AdventurersPack.ENDGAME.get());weapon.enchant(Enchantments.SHARPNESS,4);weapon.setDamageValue(73);var first=new EndgameProjectile(h.getLevel(),p,weapon);first.returning=true;first.age=55;first.returnSlot=40;first.homePack=java.util.UUID.randomUUID();first.homeSlot=110;CompoundTag tag=new CompoundTag();first.addAdditionalSaveData(tag);var next=new EndgameProjectile(AdventurersPack.ENDGAME_PROJECTILE.get(),h.getLevel());next.readAdditionalSaveData(tag);h.assertTrue(next.returning&&next.age==55&&next.returnSlot==40&&next.homeSlot==110&&next.homePack.equals(first.homePack),"Return metadata survives save/load");h.assertTrue(ItemStack.matches(weapon,next.getItem()),"Projectile saves the actual enchanted damaged item");h.succeed();}
 @GameTest(template="empty") public static void creativeThrowAddsNothing(GameTestHelper h){var p=h.makeMockPlayer();var e=new EndgameProjectile(h.getLevel(),p,new ItemStack(AdventurersPack.ENDGAME.get()));e.creativeCopy=true;h.assertTrue(e.returnWeapon(p)&&p.getInventory().isEmpty(),"Creative copy never materializes an extra weapon");h.succeed();}
 @GameTest(template="empty") public static void endgameRecipeExists(GameTestHelper h){var result=h.getLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation(AdventurersPack.ID,"endgame"));h.assertTrue(result.isPresent(),"Crafting recipe registered");h.assertTrue(result.get().getIngredients().size()==9&&result.get().getResultItem(h.getLevel().registryAccess()).is(AdventurersPack.ENDGAME.get()),"Full recipe produces Endgame");h.succeed();}
 @GameTest(template="empty",timeoutTicks=200) public static void realThrowRecallsToHand(GameTestHelper h){var p=net.minecraftforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"EndgameThrow"));var at=h.absolutePos(new net.minecraft.core.BlockPos(1,4,1));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);p.getAbilities().instabuild=false;p.getInventory().setItem(0,new ItemStack(AdventurersPack.ENDGAME.get()));p.getInventory().selected=0;p.setXRot(-30);p.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);var item=(EndgameLanceItem)AdventurersPack.ENDGAME.get();item.releaseUsing(p.getMainHandItem(),h.getLevel(),p,71980);h.assertTrue(p.getMainHandItem().isEmpty(),"Throw transfers weapon out of hand");h.succeedWhen(()->{h.assertTrue(p.getMainHandItem().is(AdventurersPack.ENDGAME.get()),"Flying projectile automatically recalls to hand");h.assertTrue(p.getMainHandItem().getDamageValue()==0,"Throw does not wear the lance");});}
 @GameTest(template="empty") public static void shortChargeDoesNotThrow(GameTestHelper h){var p=h.makeMockPlayer();p.getInventory().setItem(0,new ItemStack(AdventurersPack.ENDGAME.get()));p.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);((EndgameLanceItem)AdventurersPack.ENDGAME.get()).releaseUsing(p.getMainHandItem(),h.getLevel(),p,71995);h.assertTrue(p.getMainHandItem().is(AdventurersPack.ENDGAME.get())&&p.getMainHandItem().getDamageValue()==0,"Short charge does not consume or throw weapon");h.succeed();}
}
